map-layer-style--map-layer-style-default.js:
import { VlMap, VlMapBaseLayerGRBGray, VlMapFeaturesLayer, VlMapLayerStyle } from '@domg-wc/map';

// Eén polygoon in Lambert 72 (EPSG:31370), met de property label.
document.querySelector('vl-map-features-layer').features = {
    type: 'FeatureCollection',
    features: [
        {
            type: 'Feature',
            geometry: {
                type: 'Polygon',
                coordinates: [
                    [
                        [147055.0, 197908.0],
                        [157055.0, 197908.0],
                        [157055.0, 187908.0],
                        [147055.0, 187908.0],
                        [147055.0, 197908.0],
                    ],
                ],
            },
            properties: { label: 'Text' },
        },
    ],
};

